FColor SourceCreationFill(const FRenderTargetReq& R) {
 if(R.Color.IsEmpty()) return FColor::White; if(R.Color.Num()!=4) throw std::runtime_error("Optional source fill requires four RGBA bytes"); for(double V:R.Color) if(!FMath::IsFinite(V) || V<0 || V>255 || V!=FMath::FloorToDouble(V)) throw std::runtime_error("Source fill RGBA integer bytes0..255 required"); return FColor(uint8(R.Color[0]),uint8(R.Color[1]),uint8(R.Color[2]),uint8(R.Color[3]));
}
void FillBGRA8SourceMip(uint8* Data,int64 Bytes,const FColor& Fill) {
 if(!Data || Bytes<0 || Bytes%4!=0) throw std::runtime_error("Native BGRA8 mip byte layout required"); for(int64 I=0;I<Bytes;I+=4) { Data[I]=Fill.B; Data[I+1]=Fill.G; Data[I+2]=Fill.R; Data[I+3]=Fill.A; }
}
