UTextureRenderTarget* ResolveConversionTarget(const FRenderTargetReq& R,int32& Width,int32& Height,int32& Slices) {
 if(!IsInGameThread() || !GEditor || GEditor->PlayWorld || R.SourceTexturePath.IsEmpty() || R.SourceTexturePath.Len()>2048) throw std::runtime_error("Stopped editor/bounded loaded render target path required"); auto* T=FindObject<UTextureRenderTarget>(nullptr,*R.SourceTexturePath); if(!IsValid(T) || !T->IsAsset() || T->IsTemplate() || T->HasAnyFlags(RF_Transient|RF_NeedLoad|RF_NeedPostLoad) || T->GetPathName()!=R.SourceTexturePath) throw std::runtime_error("Loaded persistent render target required"); const auto* Class=T->GetClass(); if(Class==UTextureRenderTarget2D::StaticClass()) { const auto* A=CastChecked<UTextureRenderTarget2D>(T); Width=A->SizeX; Height=A->SizeY; Slices=1; } else if(Class==UTextureRenderTargetCube::StaticClass()) { Width=Height=CastChecked<UTextureRenderTargetCube>(T)->SizeX; Slices=6; } else if(Class==UTextureRenderTargetVolume::StaticClass()) { const auto* A=CastChecked<UTextureRenderTargetVolume>(T); Width=A->SizeX; Height=A->SizeY; Slices=A->SizeZ; } else if(Class==UTextureRenderTarget2DArray::StaticClass()) { const auto* A=CastChecked<UTextureRenderTarget2DArray>(T); Width=A->SizeX; Height=A->SizeY; Slices=A->Slices; } else throw std::runtime_error("Exact native2D/cube/volume/2D-array target types required"); return T;
}
